name = #{name}, author = #{author}, cover_url = #{coverUrl}, category = #{category}, intro = #{intro}, status = #{status}, word_count = #{wordCount}, latest_chapter_id = #{latestChapterId}, latest_chapter_name = #{latestChapterName}, chapter_count = #{chapterCount}, source_name = #{sourceName}, source_url = #{sourceUrl}, info_url = #{infoUrl}, remark = #{remark}, visibility = #{visibility}, update_time = CURRENT_TIMESTAMP
