UPDATE t_book
SET chapter_count = (SELECT COUNT(1) FROM t_chapter c WHERE c.book_id = #{bookId}),
    latest_chapter_id = (SELECT c.id FROM t_chapter c WHERE c.book_id = #{bookId}
                         ORDER BY c.chapter_no DESC LIMIT 1),
    latest_chapter_name = (SELECT c.title FROM t_chapter c WHERE c.book_id = #{bookId}
                           ORDER BY c.chapter_no DESC LIMIT 1),
    update_time = CURRENT_TIMESTAMP
WHERE id = #{bookId}

